#include <cpp.h>

// Function to retrieve extended statistics from a Memcache server
Array getExtendedMemcacheStats(const String& type = null_string, int slabid = 0, int limit = 100) {
    Array stats;
    Memcached* memcached = memcached_create(NULL);

    if (!memcached) {
        return Array(); // Return empty array if connection fails
    }

    memcached_return rc = memcached_server_list_add(memcached, NULL, 0, NULL);
    if (rc != MEMCACHED_SUCCESS) {
        memcached_destroy(memcached);
        return Array(); // Return empty array if server list addition fails
    }

    memcached_stat_st* stats_data = memcached_stat(memcached, NULL, 0, &rc);
    if (rc != MEMCACHED_SUCCESS || !stats_data) {
        memcached_destroy(memcached);
        return Array(); // Return empty array if statistics retrieval fails
    }

    for (size_t i = 0; i < memcached_stat_count(stats_data); ++i) {
        memcached_stat_st* stat = memcached_stat_get(stats_data, i);
        String server_key = String::format("%s:%d", stat->hostname, stat->port);
        stats.append(server_key, stat->stats);
    }

    memcached_stat_free(stats_data);
    memcached_destroy(memcached);

    return stats;
}

